// Package `nft` draws the Settlers, pixel-art gnomes.
// The art is dedicated to the public domain under CC0 1.0, see Credits.
package nft

const (
	// Style is the ID of the art style.
	Style = "settlers-v1"

	// Credits is the license of the art.
	Credits = "The art of the Settlers is dedicated to the public domain under " +
		"[CC0 1.0 Universal](https://creativecommons.org/publicdomain/zero/1.0/)"
)

package nft

const (
	gridW = 24
	gridH = 32
	half  = 12 // columns of the left half, where rows are written
)

// span is a horizontal range of pixels, x0 to x1 inclusive.
type span struct{ y, x0, x1 int }

// BuildGrid returns the pixel grid of a gnome, as 32 rows of 24 palette keys ('.' is transparent).
// Traits must be valid.
func BuildGrid(t Traits) []string {
	g := buildGrid(t)

	rows := make([]string, gridH)
	for y := 0; y < gridH; y++ {
		row := make([]byte, gridW)
		for x := 0; x < gridW; x++ {
			c := g[y*gridW+x]
			if c == 0 {
				c = '.'
			}
			row[x] = c
		}
		rows[y] = string(row)
	}
	return rows
}

// buildGrid draws all the layers of a gnome. The grid has a byte per pixel, row by row, and 0 is transparent.
func buildGrid(t Traits) []byte {
	if err := t.Validate(); err != nil {
		panic("settlers: " + err.Error())
	}

	g := make([]byte, gridW*gridH)

	draw(g, body, 19)
	if t.Beard == 0 {
		draw(g, head+headNoBeard, 13)
	} else {
		switch t.Beard {
		case 1:
			draw(g, beardLong, 19)
		case 2:
			draw(g, beardPointy, 19)
		default:
			draw(g, beardRound, 19)
		}
		draw(g, head+headBeard, 13)
	}

	if t.Glasses > 0 {
		for _, p := range glassesFrame {
			put(g, p[0], p[1], 'g')
		}
		for _, p := range glassesEyes {
			put(g, p[0], p[1], 'e')
		}
	}

	if t.HatShape == 0 {
		draw(g, hatTall, 0)
	} else {
		drawBentHat(g, t.Flip == 1)
	}
	draw(g, brim, 11)
	draw(g, boots, 28)
	return g
}

// draw draws rows, that are the left half of the sprite, starting at row y0. The right half is
// the left half mirrored, where light tones are swapped by their shaded twin.
func draw(g []byte, rows string, y0 int) {
	for i := 0; i*half < len(rows); i++ {
		y := y0 + i
		if y < 0 || y >= gridH {
			continue
		}

		row := rows[i*half : (i+1)*half]
		for j := 0; j < half; j++ {
			c := row[j]
			if c != '.' {
				g[y*gridW+j] = c
				g[y*gridW+gridW-1-j] = swapTable[c]
			}
		}
	}
}

func put(g []byte, x, y int, c byte) {
	if x >= 0 && x < gridW && y >= 0 && y < gridH {
		g[y*gridW+x] = c
	}
}

// drawBentHat draws the hat with the tip that falls to the right, or to the left when flipped.
//
// It is written without function calls (no closures or helpers), because they are the most
// expensive thing in Gno. The fill has a border of one cell, so neighbors never need a bounds check.
func drawBentHat(g []byte, flip bool) {
	const (
		rows   = coneY0 + len(coneK) + 1 // rows of the hat, one more than the cone for its outline
		stride = gridW + 2
	)
	var fill [(rows + 2) * stride]bool // No maps are used to keep it deterministic

	for i, k := range coneK {
		for x := half - k; x < half+k; x++ {
			if flip {
				fill[(coneY0+i+1)*stride+gridW-x] = true // mirrored column gridW-1-x, plus the border
			} else {
				fill[(coneY0+i+1)*stride+x+1] = true
			}
		}
	}
	for _, s := range tailSpans {
		for x := s.x0; x <= s.x1; x++ {
			if flip {
				fill[(s.y+1)*stride+gridW-x] = true
			} else {
				fill[(s.y+1)*stride+x+1] = true
			}
		}
	}

	for y := 0; y < rows; y++ {
		for x := 0; x < gridW; x++ {
			i := (y+1)*stride + x + 1
			if !fill[i] {
				continue
			}
			left, right, up, down := fill[i-1], fill[i+1], fill[i-stride], fill[i+stride]

			// Shading
			c := byte('H')
			if !left {
				if y%2 == 1 {
					c = 'h'
				}
			} else if !right || !down {
				c = 'j'
			}
			g[y*gridW+x] = c

			// Outline. It only touches pixels that are not part of the hat, so it doesn't matter
			// that it is done in the same pass as the shading.
			if !left && x > 0 {
				g[y*gridW+x-1] = 'o'
			}
			if !right && x < gridW-1 {
				g[y*gridW+x+1] = 'o'
			}
			if !up && y > 0 {
				g[(y-1)*gridW+x] = 'o'
			}
			if !down {
				g[(y+1)*gridW+x] = 'o'
			}
		}
	}
}

package nft

import (
	"encoding/base64"
	"strconv"
)

// CanonicalSize is the width and height in pixels of the image used for NFTs.
const CanonicalSize = 512

// Options are the options to render a gnome.
type Options struct {
	// Size is the width and the height of the image in pixels, because the image is a square.
	// Multiples of 32 keep every art pixel as a whole number of screen pixels.
	// Zero omits the width and height, so that the image scales to its container.
	Size int

	// NoBackground omits the background.
	NoBackground bool

	// BackgroundColor replaces the color of the background, in "#rrggbb" format.
	BackgroundColor string
}

// RenderSVG renders the gnome as an SVG document.
// Traits must be valid.
// The same traits and options always give the same bytes.
func RenderSVG(t Traits, o Options) string {
	return render(t, o, &rawSyntax)
}

// RenderSeed renders the gnome of a seed as an SVG document.
func RenderSeed(seed string, o Options) string {
	return RenderSVG(NewTraits(seed), o)
}

// RenderDataURI renders the gnome as a "data:image/svg+xml;charset=utf-8," URI, percent-encoded.
//
// Cheapest way to embed a gnome.
// SVG is written encoded, instead of encoding it afterwards.
// Traits must be valid.
func RenderDataURI(t Traits, o Options) string {
	return "data:image/svg+xml;charset=utf-8," + render(t, o, &uriSyntax)
}

// DataURI encodes an SVG document as a "data:image/svg+xml;base64," URI.
// It is slower than RenderDataURI, use it when Base64 is needed.
func DataURI(svg string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

// syntax define the fixed pieces of the SVG document, that are the same for every gnome.
type syntax struct {
	open       string // start of the svg element, up to its size
	widthOpen  string
	heightOpen string
	sizeClose  string
	openEnd    string // end of the start of the svg element
	rectOpen   string // background, before its color
	rectClose  string
	pathOpen   string // before the color
	pathMid    string // after the color, before the segments
	pathClose  string
	end        string
	mHead      []string // start of a segment, by x
}

// rawSyntax contains the fixed pieces of the SVG document.
var rawSyntax = syntax{
	open:       `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-4 0 32 32"`,
	widthOpen:  ` width="`,
	heightOpen: `" height="`,
	sizeClose:  `"`,
	openEnd:    ` shape-rendering="crispEdges">`,
	rectOpen:   `<rect x="-4" width="32" height="32" fill="#`,
	rectClose:  `"/>`,
	pathOpen:   `<path fill="#`,
	pathMid:    `" d="`,
	pathClose:  `"/>`,
	end:        `</svg>`,
	mHead:      rawMHead[:],
}

// uriSyntax contains the fixes pieces of the SVG document encoded for data URI.
var uriSyntax = syntax{
	open:       `%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%22-4%200%2032%2032%22`,
	widthOpen:  `%20width=%22`,
	heightOpen: `%22%20height=%22`,
	sizeClose:  `%22`,
	openEnd:    `%20shape-rendering=%22crispEdges%22%3E`,
	rectOpen:   `%3Crect%20x=%22-4%22%20width=%2232%22%20height=%2232%22%20fill=%22%23`,
	rectClose:  `%22/%3E`,
	pathOpen:   `%3Cpath%20fill=%22%23`,
	pathMid:    `%22%20d=%22`,
	pathClose:  `%22/%3E`,
	end:        `%3C/svg%3E`,
	mHead:      uriMHead[:],
}

// maxGroups is the biggest number of different colors of a gnome: 22 keys.
const maxGroups = 24

// render draws the gnome:
//   - Pixels are scanned row by row, and horizontal runs of the same key are one segment.
//   - Segments are grouped by color, in the order in which each color appears first.
func render(t Traits, o Options, s *syntax) string {
	g := buildGrid(t)
	bg := bgColors[t.Background]
	if o.BackgroundColor != "" {
		bg = hexColor(o.BackgroundColor)
	}

	var (
		groupOf    [128]uint8 // group of a key plus one, or 0 when the key was not seen
		groupColor [maxGroups]string
		groupPath  [maxGroups]string
		groups     int
	)
	for y := 0; y < gridH; y++ {
		row := g[y*gridW : (y+1)*gridW]
		for x := 0; x < gridW; {
			c := row[x]
			if c == 0 {
				x++
				continue
			}

			n := 1
			for x+n < gridW && row[x+n] == c {
				n++
			}

			gi := int(groupOf[c])
			if gi == 0 {
				// First time that the key is seen, its color might be already used by another key
				color := colorOf(t, c)
				for i := 0; i < groups; i++ {
					if groupColor[i] == color {
						gi = i + 1
						break
					}
				}

				if gi == 0 {
					groupColor[groups] = color
					groups++
					gi = groups
				}

				groupOf[c] = uint8(gi)
			}

			gi--
			groupPath[gi] += s.mHead[x] + nums[y] + runTail[n]
			x += n
		}
	}

	out := s.open
	if o.Size > 0 {
		px := strconv.Itoa(o.Size)
		out += s.widthOpen + px + s.heightOpen + px + s.sizeClose
	}

	out += s.openEnd
	if !o.NoBackground {
		out += s.rectOpen + bg + s.rectClose
	}

	for i := 0; i < groups; i++ {
		out += s.pathOpen + groupColor[i] + s.pathMid + groupPath[i] + s.pathClose
	}
	return out + s.end
}

// colorOf returns the color of a palette key, in hex digits.
func colorOf(t Traits, key byte) string {
	if c := fixedColor(key); c != "" {
		return c
	}

	skin := int(t.Skin) * 3
	hat := int(t.Hat) * 3
	beard := int(t.BeardColor) * 3
	tunic := int(t.Tunic) * 3

	switch key {
	case 't':
		return skinColors[skin]
	case 's':
		return skinColors[skin+1]
	case 'u':
		return skinColors[skin+2]
	case 'h':
		return hatColors[hat]
	case 'H':
		return hatColors[hat+1]
	case 'j':
		return hatColors[hat+2]
	case 'w':
		return beardColors[beard]
	case 'W':
		return beardColors[beard+1]
	case 'x':
		return beardColors[beard+2]
	case 'c':
		return tunicColors[tunic]
	case 'C':
		return tunicColors[tunic+1]
	case 'd':
		return tunicColors[tunic+2]
	case 'g':
		return glassesColors[t.Glasses-1]
	}
	panic("unknown palette key " + string(rune(key)))
}

// hexColor checks a "#rrggbb" color and returns its hex digits.
func hexColor(color string) string {
	if len(color) != 7 || color[0] != '#' {
		panic("invalid background color, expected #rrggbb")
	}

	for i := 1; i < 7; i++ {
		c := color[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			panic("invalid background color, expected #rrggbb")
		}
	}
	return color[1:]
}

package nft

import (
	"crypto/sha256"
	"errors"
)

var (
	beardColorNames = [...]string{"White", "Grey", "Ginger", "Brown"}
	beardShapeNames = [...]string{"None", "Long", "Pointy", "Round"}
	backgroundNames = [...]string{"Sky", "Sand", "Mint", "Lilac", "Blush"}
	glassesNames    = [...]string{"None", "Black", "Gold", "Red", "Teal"}
	hatNames        = [...]string{"Red", "Blue", "Green", "Purple", "Orange"}
	skinNames       = [...]string{"Light", "Medium", "Deep"}
	tunicNames      = [...]string{"Sky", "Leaf", "Clay", "Rose", "Sun"}
)

// Attribute is a named trait of a gnome.
type Attribute struct {
	Type  string
	Value string
}

// Traits describe a gnome.
type Traits struct {
	Skin       uint8
	Hat        uint8
	BeardColor uint8
	Tunic      uint8
	Background uint8
	HatShape   uint8 // 0 pointy, 1 bent
	Flip       uint8 // 0 or 1, no effect on pointy hats
	Glasses    uint8
	Beard      uint8
}

// NewTraits derives the traits of the gnome from a seed.
// A single seed always generate the same traits.
// Use `Validate()` to check traits before drawing.
func NewTraits(seed string) Traits {
	data := sha256.Sum256([]byte(seed))
	t := Traits{
		Skin:       data[0] % 3,
		Hat:        data[1] % 5,
		BeardColor: data[2] % 4,
		Tunic:      data[3] % 5,
		Background: data[4] % 5,
		Flip:       data[6] & 1,
	}

	// Gnome with bent hat, about 35%
	if data[5] < 90 {
		t.HatShape = 1
	}

	// Gnome with glasses, about 30%
	if data[7] < 77 {
		t.Glasses = data[8]%4 + 1
	}

	// Gnome without beard is a rare trait, about 4%
	if data[9] >= 10 {
		t.Beard = data[10]%3 + 1
	}
	return t
}

// Validate checks that all the traits are in range.
func (t Traits) Validate() error {
	switch {
	case t.Skin > 2:
		return errors.New("invalid skin")
	case t.Hat > 4:
		return errors.New("invalid hat color")
	case t.BeardColor > 3:
		return errors.New("invalid beard color")
	case t.Tunic > 4:
		return errors.New("invalid tunic")
	case t.Background > 4:
		return errors.New("invalid background")
	case t.HatShape > 1:
		return errors.New("invalid hat shape")
	case t.Flip > 1:
		return errors.New("invalid flip")
	case t.Glasses > 4:
		return errors.New("invalid glasses")
	case t.Beard > 3:
		return errors.New("invalid beard")
	}
	return nil
}

// Normalized returns the traits with the flip cleared when it has no effect.
// Two traits that draw the same gnome have the same normalized traits, so
// this is the value to compare and to keep when gnomes must be different.
func (t Traits) Normalized() Traits {
	// Clear trait when hat is pointy.
	if t.HatShape == 0 {
		t.Flip = 0
	}
	return t
}

// Attributes returns the traits of a gnome with their names.
// It panics when traits are not valid.
func (t Traits) Attributes() []Attribute {
	if err := t.Validate(); err != nil {
		panic(err.Error())
	}

	hat := "Pointed"
	if t.HatShape == 1 {
		hat = "Bent tip (right)"
		if t.Flip == 1 {
			hat = "Bent tip (left)"
		}
	}

	return []Attribute{
		{"Skin", skinNames[t.Skin]},
		{"Hat color", hatNames[t.Hat]},
		{"Hat", hat},
		{"Beard color", beardColorNames[t.BeardColor]},
		{"Beard", beardShapeNames[t.Beard]},
		{"Tunic", tunicNames[t.Tunic]},
		{"Glasses", glassesNames[t.Glasses]},
		{"Background", backgroundNames[t.Background]},
	}
}

// Pack packs the traits in 20 bits.
func Pack(t Traits) uint32 {
	// Bits:
	//   0-1   skin
	//   2-4   hat
	//   5-6   beard color
	//   7-9   tunic
	//   10-12 background
	//   13    hat shape
	//   14    flip
	//   15-17 glasses
	//   18-19 beard
	return uint32(t.Skin) |
		uint32(t.Hat)<<2 |
		uint32(t.BeardColor)<<5 |
		uint32(t.Tunic)<<7 |
		uint32(t.Background)<<10 |
		uint32(t.HatShape)<<13 |
		uint32(t.Flip)<<14 |
		uint32(t.Glasses)<<15 |
		uint32(t.Beard)<<18
}

// Unpack unpacks the traits.
// It does not check the values, use FromPacked for untrusted input.
func Unpack(v uint32) Traits {
	return Traits{
		Skin:       uint8(v & 3),
		Hat:        uint8((v >> 2) & 7),
		BeardColor: uint8((v >> 5) & 3),
		Tunic:      uint8((v >> 7) & 7),
		Background: uint8((v >> 10) & 7),
		HatShape:   uint8((v >> 13) & 1),
		Flip:       uint8((v >> 14) & 1),
		Glasses:    uint8((v >> 15) & 7),
		Beard:      uint8((v >> 18) & 3),
	}
}

// FromPacked unpacks traits and checks them.
func FromPacked(v uint32) (Traits, error) {
	if v>>20 != 0 {
		return Traits{}, errors.New("invalid packed traits")
	}

	t := Unpack(v)
	if err := t.Validate(); err != nil {
		return Traits{}, err
	}
	return t, nil
}

package escrow_v4

// Milestone-based escrow: on-chain freelance service contracts for Memba.
// Successor of escrow_v3 with the same user API; see DESIGN.md for what
// changed and why.
//
// Flow: CreateContract → FundMilestone → CompleteMilestone → ReleaseFunds
// Disputes: RaiseDispute → admin ResolveDispute (or ClaimDisputeTimeout after
//           AutoResolveBlks)
// Timeouts: ClaimRefund (a funded milestone nobody completed, after
//           AutoRefundBlks); ExpireUnfunded (a contract never funded, after
//           UnfundedExpiryBlks)
// Cleanup:  ArchiveContract (client deletes a settled contract; the chain
//           refunds the freed storage deposit to the signer)
//
// Invariants:
//   - State is updated before any coins are sent.
//   - realm balance >= TotalLiabilities() (NF-2).
//   - A contract is open until it is completed or cancelled; an open contract
//     holds one of its client's MaxActivePerClient slots.
//   - completed and cancelled are absorbing and hold no escrowed funds.
//
// Caller authentication: every crossing entrypoint checks cur.IsCurrent() and
// reads the caller from cur.Previous(). Every use of the unsafe runtime
// package is in origin.gno. Read-only views are in views.gno.

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/samcrew/avl"
	cfg "gno.land/r/samcrew/memba_market_config"
)

// ── Constants ────────────────────────────────────────────────

// laneService is this engine's lane key into the DAO fee spine
// (memba_market_config), seeded there at 200 bps.
const laneService = "service"

const (
	// PlatformFeePct is only the fail-safe fallback rate (see resolveFee); the
	// live rate is cfg.GetFeeBPS(laneService), read at each payout.
	PlatformFeePct = 2
	// CancelFeePct is paid to the freelancer from each funded milestone when
	// the client cancels. Escrow-internal, not a protocol fee.
	CancelFeePct = 5
	// Timeouts, in blocks, as in v3 (sized at 3 s per block; at gnoland-1's
	// ~3.3 s they are ~33 and ~31 days). Blocks inside a pause's blocking
	// window do not count (see the pause section).
	AutoRefundBlks  = int64(864000)
	AutoResolveBlks = int64(806400)
	// UnfundedExpiryBlks: a contract none of whose milestones was ever funded
	// can be cancelled by anyone after this many blocks, freeing its slot.
	UnfundedExpiryBlks = AutoRefundBlks

	MaxTitleLen        = 200  // bytes, after sanitising (also bounds the input)
	MaxDescLen         = 5000 // bytes, after sanitising (also bounds the input)
	MaxMilestones      = 20
	MinMilestoneAmount = int64(1000) // 0.001 GNOT: below ~50 ugnot a 2% fee truncates to 0
	// maxMilestonesArgLen bounds the raw milestones argument before parsing:
	// 20 entries of a 200-byte title, a 19-digit amount and separators, with
	// room for surrounding spaces.
	maxMilestonesArgLen = MaxMilestones * (MaxTitleLen + 64)

	// MaxActivePerClient bounds the open contracts one client address may
	// hold. It counts only contracts the address created, never those naming
	// it as freelancer, so nobody can use up someone else's slots, and it
	// bounds what one key can lock (five of the largest contracts are about
	// 15 GNOT of storage deposit). There is no global cap: nothing iterates
	// over every contract, so a global number would bound no gas and would
	// only give a funded attacker a switch to turn escrow off for everyone.
	MaxActivePerClient = 5
)

// ── Types ────────────────────────────────────────────────────

type ContractStatus string

const (
	StatusActive    ContractStatus = "active"
	StatusCompleted ContractStatus = "completed"
	StatusDisputed  ContractStatus = "disputed"
	StatusCancelled ContractStatus = "cancelled"
)

type MilestoneStatus string

const (
	MsPending   MilestoneStatus = "pending"
	MsFunded    MilestoneStatus = "funded"
	MsCompleted MilestoneStatus = "completed"
	MsReleased  MilestoneStatus = "released"
	MsDisputed  MilestoneStatus = "disputed"
	MsRefunded  MilestoneStatus = "refunded"
)

type Contract struct {
	ID          string
	Client      address
	Freelancer  address
	Title       string
	Description string
	Status      ContractStatus
	CreatedAt   int64 // block height
	Milestones  []Milestone

	createdPauseMark int64 // pausedBlocksAt(CreatedAt), for UnfundedExpiryBlks
}

type Milestone struct {
	ID               int // equals the milestone's index
	Title            string
	Amount           int64 // ugnot
	Status           MilestoneStatus
	FundedAt         int64           // block height (0 if not funded)
	CompletedAt      int64           // block height (0 if not completed)
	DisputedAt       int64           // block height (0 if not disputed)
	PreDisputeStatus MilestoneStatus // status before dispute (MsFunded or MsCompleted)

	fundedPauseMark   int64 // pausedBlocksAt(FundedAt), for AutoRefundBlks
	disputedPauseMark int64 // pausedBlocksAt(DisputedAt), for AutoResolveBlks
}

// ── State ────────────────────────────────────────────────────

var (
	contracts     *avl.Tree // id -> *Contract; live (not archived) contracts only
	clientSlots   *avl.Tree // client address -> int open contracts (removed on archive once 0); "c/<client>/<id>" -> nil client index
	nextID        int       // monotonic, never reused
	activeCount   int       // open contracts
	archivedCount int
	totalLiable   int64 // NF-2: ugnot owed to funded, completed and disputed milestones
)

func init() {
	contracts = avl.NewTree()
	clientSlots = avl.NewTree()
}

// resolveFee reads the "service" lane fee (bps) and treasury from the DAO fee
// spine at payout time. The config getters are pure and non-failing; on an
// out-of-range rate or an empty or malformed treasury this falls back to the
// frozen rate and the realm's fee recipient rather than reverting a payout, so
// a config mistake never strands escrowed funds.
func resolveFee() (int64, address) {
	bps := int64(cfg.GetFeeBPS(laneService))
	if bps < 0 || bps > cfg.MaxFeeBPS {
		bps = int64(PlatformFeePct) * 100
	}
	treasury := cfg.GetTreasury()
	if treasury == "" || !treasury.IsValid() {
		treasury = feeRecipient
	}
	return bps, treasury
}

// callerOf returns the immediate caller of a crossing entrypoint.
func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return cur.Previous().Address()
}

// ── Contract lifecycle ───────────────────────────────────────

// CreateContract creates a new escrow contract with milestones, as the
// caller's client. Milestones format: "title1:amount1,title2:amount2".
// The caller must be a user (a direct call or the user's own run script), so a
// realm cannot mint client identities with cur.Sub to hold slots.
func CreateContract(cur realm, freelancer address, title, description, milestones string) string {
	assertAcceptsNewMoney()
	caller := callerOf(cur)
	if !cur.Previous().IsUser() {
		panic("CreateContract must be called by a user, not a realm")
	}
	if !freelancer.IsValid() {
		panic("invalid freelancer address")
	}
	if freelancer == caller {
		panic("cannot hire yourself")
	}
	if len(title) == 0 {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	cleanTitle := cleanText(title, "title", MaxTitleLen)
	if strings.TrimSpace(cleanTitle) == "" {
		panic("title must contain visible characters")
	}
	cleanDesc := cleanText(description, "description", MaxDescLen)

	ms := parseMilestones(milestones)
	if len(ms) == 0 {
		panic("at least one milestone required")
	}
	if len(ms) > MaxMilestones {
		panic(ufmt.Sprintf("maximum %d milestones allowed", MaxMilestones))
	}

	takeSlot(caller)
	n := nextID
	id := strconv.Itoa(n)
	nextID++
	clientSlots.Set(indexKey(caller, n), nil) // client index (views.gno)
	now := runtime.ChainHeight()
	contracts.Set(id, &Contract{
		ID:               id,
		Client:           caller,
		Freelancer:       freelancer,
		Title:            cleanTitle,
		Description:      cleanDesc,
		Status:           StatusActive,
		CreatedAt:        now,
		Milestones:       ms,
		createdPauseMark: pausedBlocksAt(now),
	})

	chain.Emit("ContractCreated",
		"id", id,
		"client", caller.String(),
		"freelancer", freelancer.String(),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// FundMilestone deposits exactly the milestone amount. Client only, and only
// as a direct user call: the tx-level send lands on the message's target
// realm, so from an intermediary realm the coins would never reach escrow
// while the milestone was marked funded.
func FundMilestone(cur realm, contractId string, milestoneIdx int) {
	assertAcceptsNewMoney()
	caller := callerOf(cur)
	if !cur.Previous().IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can fund")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsPending {
		panic("milestone already funded or processed")
	}
	requireExactSend(ms.Amount, cur.Previous())

	now := runtime.ChainHeight()
	ms.Status = MsFunded
	ms.FundedAt = now
	ms.fundedPauseMark = pausedBlocksAt(now)
	totalLiable += ms.Amount

	chain.Emit("MilestoneFunded",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"amount", strconv.FormatInt(ms.Amount, 10),
	)
}

// CompleteMilestone marks a funded milestone delivered. Freelancer only.
func CompleteMilestone(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Freelancer != caller {
		panic("only freelancer can mark complete")
	}
	// A disputed contract is frozen until the dispute is resolved.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot complete milestones during dispute")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}

	ms.Status = MsCompleted
	ms.CompletedAt = runtime.ChainHeight()

	chain.Emit("MilestoneCompleted",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", caller.String(),
	)
}

// ReleaseFunds pays a completed milestone to the freelancer, minus the fee.
// Client, or admin as the trusted arbiter (v3 behaviour).
func ReleaseFunds(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller && caller != admin {
		panic("only client or admin can release")
	}
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot release funds during dispute")
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsCompleted {
		panic("milestone not completed")
	}

	ms.Status = MsReleased
	settleIfFinished(c)
	totalLiable -= ms.Amount

	p := payFreelancer(cur, c, ms.Amount)

	chain.Emit("FundsReleased",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", c.Freelancer.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Disputes ─────────────────────────────────────────────────

// RaiseDispute escalates a funded or completed milestone to the admin.
// Client or freelancer.
func RaiseDispute(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller && c.Freelancer != caller {
		panic("only client or freelancer can dispute")
	}
	if !isOpen(c) {
		panic("contract is " + string(c.Status))
	}
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded && ms.Status != MsCompleted {
		panic("can only dispute funded or completed milestones")
	}

	// ClaimDisputeTimeout pays the freelancer if the work had been delivered
	// (MsCompleted) and refunds the client otherwise.
	now := runtime.ChainHeight()
	ms.PreDisputeStatus = ms.Status
	ms.Status = MsDisputed
	ms.DisputedAt = now
	ms.disputedPauseMark = pausedBlocksAt(now)
	c.Status = StatusDisputed

	chain.Emit("DisputeRaised",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"raisedBy", caller.String(),
	)
}

// ResolveDispute settles a disputed milestone. Admin only.
// refundClient=true refunds the client in full; false pays the freelancer
// minus the fee. The contract then returns to active, stays disputed if
// another milestone still is, or settles: completed if every milestone is
// released, cancelled if every milestone is released or refunded.
func ResolveDispute(cur realm, contractId string, milestoneIdx int, refundClient bool) {
	assertOpen()
	if callerOf(cur) != admin {
		panic("only admin can resolve disputes")
	}
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}

	if refundClient {
		ms.Status = MsRefunded
	} else {
		ms.Status = MsReleased
	}
	c.Status = StatusActive
	if anyMilestoneDisputed(c) {
		c.Status = StatusDisputed
	}
	settleIfFinished(c)
	totalLiable -= ms.Amount

	var p payout
	resolution := "released-to-freelancer"
	if refundClient {
		resolution = "refunded-to-client"
		send(cur, c.Client, ms.Amount)
		p = payout{net: ms.Amount, recipient: c.Client}
	} else {
		p = payFreelancer(cur, c, ms.Amount)
	}
	chain.Emit("DisputeResolved",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
		"recipient", p.recipient.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Cancellation and expiry ──────────────────────────────────

// CancelContract cancels an active contract. Client only. Funded milestones
// are refunded minus CancelFeePct, which goes to the freelancer; completed
// milestones are paid to the freelancer minus the service fee.
func CancelContract(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can cancel")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}

	// Only milestones transitioned here are paid, so a milestone already
	// refunded or released is never paid twice.
	var refunded, released []int
	for i := range c.Milestones {
		switch c.Milestones[i].Status {
		case MsFunded:
			c.Milestones[i].Status = MsRefunded
			refunded = append(refunded, i)
		case MsCompleted:
			c.Milestones[i].Status = MsReleased
			released = append(released, i)
		}
	}
	settle(c, StatusCancelled)
	for _, i := range refunded {
		totalLiable -= c.Milestones[i].Amount
	}
	for _, i := range released {
		totalLiable -= c.Milestones[i].Amount
	}

	var toClient, compensation, toFreelancer, fees, bps int64
	var treasury address
	for _, i := range refunded {
		amount := c.Milestones[i].Amount
		fee := basisPointsFee(amount, int64(CancelFeePct)*100)
		send(cur, c.Client, amount-fee)
		send(cur, c.Freelancer, fee)
		toClient += amount - fee
		compensation += fee
	}
	for _, i := range released {
		p := payFreelancer(cur, c, c.Milestones[i].Amount)
		toFreelancer += p.net
		fees += p.fee
		bps, treasury = p.bps, p.treasury
	}

	chain.Emit("ContractCancelled",
		"contractId", contractId,
		"client", c.Client.String(),
		"freelancer", c.Freelancer.String(),
		"refunded", strconv.Itoa(len(refunded)),
		"released", strconv.Itoa(len(released)),
		"refundToClient", strconv.FormatInt(toClient, 10),
		"cancelCompensation", strconv.FormatInt(compensation, 10),
		"cancelFeeBps", strconv.FormatInt(int64(CancelFeePct)*100, 10),
		"releasedToFreelancer", strconv.FormatInt(toFreelancer, 10),
		"fee", strconv.FormatInt(fees, 10),
		"bps", strconv.FormatInt(bps, 10),
		"treasury", treasury.String(),
	)
}

// ExpireUnfunded cancels a contract none of whose milestones was ever funded,
// once UnfundedExpiryBlks have passed since creation (blocking-window blocks
// excluded). Anyone may call. It frees the client's slot and moves no coins;
// it does not delete, so the storage deposit stays for the client's
// ArchiveContract.
func ExpireUnfunded(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Status != StatusActive {
		panic("contract not active")
	}
	for _, m := range c.Milestones {
		if m.Status != MsPending {
			panic("contract was funded; use ClaimRefund or CancelContract")
		}
	}
	elapsed := elapsedOpen(c.CreatedAt, c.createdPauseMark)
	if elapsed < UnfundedExpiryBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", UnfundedExpiryBlks-elapsed))
	}

	settle(c, StatusCancelled)

	chain.Emit("ContractExpired",
		"contractId", contractId,
		"client", c.Client.String(),
		"expiredBy", caller.String(),
	)
}

// ── Timeouts (permissionless) ────────────────────────────────

// ClaimRefund refunds a funded milestone nobody completed within
// AutoRefundBlks (blocking-window blocks excluded). Anyone may call; the
// client receives the funds. If no milestone then holds funds the contract is
// cancelled, pending milestones included (v3 behaviour).
func ClaimRefund(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}
	if ms.FundedAt == 0 {
		panic("milestone has no funding record")
	}
	elapsed := elapsedOpen(ms.FundedAt, ms.fundedPauseMark)
	if elapsed < AutoRefundBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoRefundBlks-elapsed))
	}

	ms.Status = MsRefunded
	if allMilestonesTerminal(c) {
		settle(c, StatusCancelled)
	}
	totalLiable -= ms.Amount

	send(cur, c.Client, ms.Amount)

	chain.Emit("RefundClaimed",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"recipient", c.Client.String(),
		"amount", strconv.FormatInt(ms.Amount, 10),
		"status", string(c.Status),
	)
}

// ClaimDisputeTimeout resolves a dispute the admin has not acted on within
// AutoResolveBlks (blocking-window blocks excluded), following the pre-dispute
// status: a delivered milestone (MsCompleted) pays the freelancer minus the
// fee, an undelivered one (MsFunded) refunds the client. Anyone may call.
func ClaimDisputeTimeout(cur realm, contractId string, milestoneIdx int) {
	assertOpen()
	c := getContract(contractId)
	ms := milestoneAt(c, milestoneIdx)
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}
	if ms.DisputedAt == 0 {
		panic("milestone has no dispute record")
	}
	elapsed := elapsedOpen(ms.DisputedAt, ms.disputedPauseMark)
	if elapsed < AutoResolveBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoResolveBlks-elapsed))
	}

	payToFreelancer := ms.PreDisputeStatus == MsCompleted
	if payToFreelancer {
		ms.Status = MsReleased
	} else {
		ms.Status = MsRefunded
	}
	c.Status = StatusActive
	if anyMilestoneDisputed(c) {
		c.Status = StatusDisputed
	}
	if allMilestonesReleased(c) {
		settle(c, StatusCompleted)
	} else if allMilestonesTerminal(c) {
		settle(c, StatusCancelled)
	}
	totalLiable -= ms.Amount

	var p payout
	resolution := "refunded-client-no-delivery"
	if payToFreelancer {
		resolution = "paid-freelancer-work-delivered"
		p = payFreelancer(cur, c, ms.Amount)
	} else {
		send(cur, c.Client, ms.Amount)
		p = payout{net: ms.Amount, recipient: c.Client}
	}
	chain.Emit("DisputeTimedOut",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
		"recipient", p.recipient.String(),
		"amount", strconv.FormatInt(p.net, 10),
		"fee", strconv.FormatInt(p.fee, 10),
		"bps", strconv.FormatInt(p.bps, 10),
		"treasury", p.treasury.String(),
		"status", string(c.Status),
	)
}

// ── Archive ──────────────────────────────────────────────────

// ArchiveContract deletes a settled contract (completed or cancelled, with
// nothing escrowed). Client only. The freed bytes shrink the realm's storage,
// and the chain refunds their storage deposit to the signer of this message
// (see DESIGN.md), so the client, who paid for the contract when creating it,
// gets that deposit back. The id is never reused. The ContractArchived event
// is the permanent record; nothing of the contract stays in realm state.
func ArchiveContract(cur realm, contractId string) {
	assertOpen()
	caller := callerOf(cur)
	c := getContract(contractId)
	if c.Client != caller {
		panic("only client can archive")
	}
	if isOpen(c) {
		panic("contract not settled: status is " + string(c.Status))
	}
	var released, refunded int64
	for _, m := range c.Milestones {
		switch m.Status {
		case MsReleased:
			released += m.Amount
		case MsRefunded:
			refunded += m.Amount
		case MsPending:
		default:
			panic("escrowed funds remain in milestone " + strconv.Itoa(m.ID))
		}
	}
	hash := contentHash(c)

	contracts.Remove(contractId)
	n, _ := strconv.Atoi(contractId)
	clientSlots.Remove(indexKey(c.Client, n))
	if clientActive(c.Client) == 0 {
		clientSlots.Remove(c.Client.String())
	}
	archivedCount++

	// milestone*Total are escrow principal, gross of fees and of the cancel
	// compensation. The storage-deposit refund is not an escrow amount: the
	// chain reports it in its own StorageUnlockEvent.
	chain.Emit("ContractArchived",
		"contractId", contractId,
		"client", c.Client.String(),
		"freelancer", c.Freelancer.String(),
		"status", string(c.Status),
		"milestoneReleasedTotal", strconv.FormatInt(released, 10),
		"milestoneRefundedTotal", strconv.FormatInt(refunded, 10),
		"contentHash", hash,
	)
}

// ── Slots and settlement ─────────────────────────────────────

// isOpen reports whether c still holds an active slot.
func isOpen(c *Contract) bool {
	return c.Status != StatusCompleted && c.Status != StatusCancelled
}

func clientActive(client address) int {
	v, ok := clientSlots.Get(client.String())
	if !ok {
		return 0
	}
	return v.(int)
}

func takeSlot(client address) {
	n := clientActive(client)
	if n >= MaxActivePerClient {
		panic(ufmt.Sprintf("limit of %d active contracts for this client reached", MaxActivePerClient))
	}
	clientSlots.Set(client.String(), n+1)
	activeCount++
}

// settle moves an open contract to a terminal status and releases its slot.
// Terminal statuses are absorbing, so this runs at most once per contract.
func settle(c *Contract, status ContractStatus) {
	if !isOpen(c) {
		panic("contract already settled")
	}
	c.Status = status
	n := clientActive(c.Client)
	if n <= 0 || activeCount <= 0 {
		panic("slot accounting underflow")
	}
	// A zero count is kept until the client archives: the client paid for
	// this tree node, and removing it here would refund its deposit to
	// whoever signs the settling message (a permissionless ClaimRefund
	// caller, the admin, the freelancer).
	clientSlots.Set(c.Client.String(), n-1)
	activeCount--
}

// settleIfFinished settles an open contract whose milestones are all released
// (completed) or all released or refunded (cancelled). A pending, funded,
// completed or disputed milestone keeps it open.
func settleIfFinished(c *Contract) {
	if !isOpen(c) {
		return
	}
	allReleased := true
	for _, m := range c.Milestones {
		if m.Status != MsReleased && m.Status != MsRefunded {
			return
		}
		if m.Status != MsReleased {
			allReleased = false
		}
	}
	if allReleased {
		settle(c, StatusCompleted)
	} else {
		settle(c, StatusCancelled)
	}
}

// ── Payments ─────────────────────────────────────────────────

type payout struct {
	recipient address
	net, fee  int64
	bps       int64
	treasury  address
}

func send(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

// payFreelancer pays amount to the freelancer minus the service fee read live
// from the fee spine, which goes to the treasury.
func payFreelancer(cur realm, c *Contract, amount int64) payout {
	bps, treasury := resolveFee()
	fee := basisPointsFee(amount, bps)
	send(cur, c.Freelancer, amount-fee)
	send(cur, treasury, fee)
	return payout{recipient: c.Freelancer, net: amount - fee, fee: fee, bps: bps, treasury: treasury}
}

// ── Helpers ──────────────────────────────────────────────────

func getContract(id string) *Contract {
	val, exists := contracts.Get(id)
	if !exists {
		panic("contract not found: " + id)
	}
	return val.(*Contract)
}

func milestoneAt(c *Contract, idx int) *Milestone {
	if idx < 0 || idx >= len(c.Milestones) {
		panic("invalid milestone index")
	}
	return &c.Milestones[idx]
}

func allMilestonesReleased(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status != MsReleased {
			return false
		}
	}
	return true
}

func anyMilestoneDisputed(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			return true
		}
	}
	return false
}

// allMilestonesTerminal reports whether no milestone holds funds (pending with
// no funds counts as terminal).
func allMilestonesTerminal(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsFunded || m.Status == MsCompleted || m.Status == MsDisputed {
			return false
		}
	}
	return true
}

// parseMilestones parses "title1:amount1,title2:amount2". Blank entries are
// skipped; any other malformed entry panics.
func parseMilestones(input string) []Milestone {
	if len(input) > maxMilestonesArgLen {
		panic(ufmt.Sprintf("milestones argument too long: %d/%d bytes", len(input), maxMilestonesArgLen))
	}
	var result []Milestone
	total := int64(0)
	for i, p := range strings.Split(input, ",") {
		p = strings.TrimSpace(p)
		if len(p) == 0 {
			continue
		}
		kv := strings.SplitN(p, ":", 2)
		if len(kv) != 2 {
			panic(ufmt.Sprintf("invalid milestone format at position %d: expected 'title:amount'", i))
		}
		title := strings.TrimSpace(kv[0])
		if len(title) == 0 {
			panic(ufmt.Sprintf("empty milestone title at position %d", i))
		}
		title = cleanText(title, ufmt.Sprintf("milestone title at position %d", i), MaxTitleLen)
		if strings.TrimSpace(title) == "" {
			panic(ufmt.Sprintf("milestone title at position %d has no visible characters", i))
		}
		amount, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || amount <= 0 {
			panic(ufmt.Sprintf("invalid milestone amount at position %d: must be positive integer", i))
		}
		if amount < MinMilestoneAmount {
			panic(ufmt.Sprintf("milestone amount too small at position %d: minimum %d ugnot", i, MinMilestoneAmount))
		}
		if amount > 9223372036854775807-total {
			panic("contract total overflows int64")
		}
		total += amount
		result = append(result, Milestone{
			ID:     len(result),
			Title:  title,
			Amount: amount,
			Status: MsPending,
		})
	}
	return result
}

// Time-boxed emergency pause.
//
// Pause (admin) has two effects:
//   - New money stops: CreateContract and FundMilestone abort until Unpause.
//   - Every other state-changing entrypoint (settlement, disputes, timeouts,
//     cancellation, expiry, archive) aborts only during the BLOCKING WINDOW,
//     the first MaxPauseBlks blocks of the pause. After that it reopens even if
//     nobody unpauses.
//
// The timeout clocks (AutoRefundBlks, AutoResolveBlks, UnfundedExpiryBlks) do
// not run inside a blocking window: each deadline moves by the paused blocks
// that fell inside it. After Unpause, a new Pause is refused for
// PauseCooldownBlks, so pause, unpause, pause cannot keep exits shut.
//
// Without the time box one admin key (after the DAO handoff, any single member
// allowed to call the emergency pause) could freeze every exit forever, and
// losing the admin key during a pause would do the same: admin rotation needs
// the admin key.
//
// Admin controls (Pause, Unpause, admin and fee-recipient rotation) are never
// paused.

const (
	// MaxPauseBlks is the blocking window: about 7 days at gnoland-1's
	// observed average of about 3.3 s per block (7*24*3600/3.3 = 183,273).
	MaxPauseBlks = int64(183273)
	// PauseCooldownBlks is the minimum gap between an Unpause and the next
	// Pause, so a pause can hold exits shut at most half of the time.
	PauseCooldownBlks = MaxPauseBlks
)

var (
	paused             bool
	pausedAt           int64 // height of the current pause; 0 when not paused
	pauseCooldownUntil int64 // first height at which Pause is accepted again
	pausedBlocksDone   int64 // blocking-window blocks of finished pauses
)

// PauseInfo is the read-back of the pause state.
type PauseInfo struct {
	Paused        bool  // set by Pause, cleared only by Unpause
	PausedAt      int64 // height of the current pause (0 when not paused)
	ExitsReopenAt int64 // PausedAt + MaxPauseBlks (0 when not paused)
	ExitsOpen     bool  // false only inside a blocking window
	CooldownUntil int64 // first height at which Pause is accepted
	PausedBlocks  int64 // total blocking-window blocks so far (clocks skip them)
}

// PauseState returns the pause state at the current height.
func PauseState() PauseInfo {
	now := runtime.ChainHeight()
	s := PauseInfo{
		Paused:        paused,
		ExitsOpen:     !inBlockingWindow(now),
		CooldownUntil: pauseCooldownUntil,
		PausedBlocks:  pausedBlocksAt(now),
	}
	if paused {
		s.PausedAt = pausedAt
		s.ExitsReopenAt = pausedAt + MaxPauseBlks
	}
	return s
}

// IsPaused reports whether the pause flag is set. Exits may already have
// reopened: see PauseState().ExitsOpen.
func IsPaused() bool { return paused }

// Pause stops new money and, for MaxPauseBlks, every other state change.
// Admin only. Refused while paused and during the cooldown after an Unpause.
func Pause(cur realm) {
	assertAdmin(cur)
	now := runtime.ChainHeight()
	if paused {
		panic("already paused")
	}
	if now < pauseCooldownUntil {
		panic("pause cooldown: next pause allowed at block " + strconv.FormatInt(pauseCooldownUntil, 10))
	}
	paused = true
	pausedAt = now
	chain.Emit("Paused",
		"at", strconv.FormatInt(now, 10),
		"exitsReopenAt", strconv.FormatInt(now+MaxPauseBlks, 10),
	)
}

// Unpause resumes normal operation and starts the cooldown. Admin only.
func Unpause(cur realm) {
	assertAdmin(cur)
	now := runtime.ChainHeight()
	if !paused {
		panic("not paused")
	}
	pausedBlocksDone = pausedBlocksAt(now)
	paused = false
	pausedAt = 0
	pauseCooldownUntil = now + PauseCooldownBlks
	chain.Emit("Unpaused",
		"at", strconv.FormatInt(now, 10),
		"cooldownUntil", strconv.FormatInt(pauseCooldownUntil, 10),
	)
}

// inBlockingWindow reports whether now falls in the first MaxPauseBlks blocks
// of the current pause.
func inBlockingWindow(now int64) bool {
	return paused && now < pausedAt+MaxPauseBlks
}

// pausedBlocksAt returns the blocking-window blocks up to now, finished pauses
// included. Timeout clocks subtract the growth of this value.
func pausedBlocksAt(now int64) int64 {
	total := pausedBlocksDone
	if paused {
		end := now
		if end > pausedAt+MaxPauseBlks {
			end = pausedAt + MaxPauseBlks
		}
		total += end - pausedAt
	}
	return total
}

// assertAcceptsNewMoney guards CreateContract and FundMilestone.
func assertAcceptsNewMoney() {
	if paused {
		panic("realm is paused — no new contracts or funding until unpaused")
	}
}

// assertOpen guards every other state-changing user and admin entrypoint.
func assertOpen() {
	if inBlockingWindow(runtime.ChainHeight()) {
		panic("realm is paused — exits reopen at block " + strconv.FormatInt(pausedAt+MaxPauseBlks, 10))
	}
}

// elapsedOpen returns the blocks since `since` that fell outside any blocking
// window, given pausedBlocksAt(since) recorded as mark.
func elapsedOpen(since, mark int64) int64 {
	now := runtime.ChainHeight()
	return now - since - (pausedBlocksAt(now) - mark)
}

// ── Admin authority and the fallback fee recipient ──────────────────────
//
// No authority is compiled in. `admin` and `feeRecipient` are seeded at
// package load from the publishing transaction's signer (on gnoland-1 the
// samcrew namespace multisig), and every gate reads the mutable variables.
// Realms are immutable and mainnet has no faucet, so a compile-time authority
// could never be corrected; losing it would disable Pause/Unpause and
// ResolveDispute, the only path that settles a dispute before its timeout.
//
// Both rotations are TWO-STEP: the current admin stages an address, and that
// address must accept with its own transaction. A one-step setter could hand
// the role to an address that cannot act (a typo, an unfunded key), with no
// way back. The admin can abort a staged proposal without the target.
//
// Rotation stays available while paused. It needs the current admin key, so
// it cannot rescue a pause after that key is lost; the pause's time box
// (pause section above) is what keeps exits from freezing.

var (
	// admin is the live authority, seeded with the publisher at load.
	admin address = publisherAtLoad()
	// pendingAdmin is the staged successor; "" when none.
	pendingAdmin address

	// feeRecipient receives the protocol fee only when memba_market_config
	// reports no treasury (see resolveFee). Seeded with the publisher.
	feeRecipient address = publisherAtLoad()
	// pendingFeeRecipient is the staged successor; "" when none.
	pendingFeeRecipient address
)

// assertAdmin rejects a stale or sibling `cur`, then checks the caller.
func assertAdmin(cur realm) {
	if callerOf(cur) != admin {
		panic("unauthorized: only admin may perform this action")
	}
}

// ── Admin rotation ───────────────────────────────────────────

// TransferOwnership stages a handoff to newAdmin. Admin only. Calling it again
// replaces the staged address.
func TransferOwnership(cur realm, newAdmin address) {
	assertAdmin(cur)
	if !newAdmin.IsValid() {
		panic("newAdmin must be a valid address")
	}
	pendingAdmin = newAdmin
	chain.Emit("OwnershipTransferStarted", "pending", newAdmin.String())
}

// AcceptOwnership completes the handoff. Only the staged address may call it,
// so the outgoing admin cannot collapse the two steps into one.
func AcceptOwnership(cur realm) {
	caller := callerOf(cur)
	if pendingAdmin == "" {
		panic("no pending ownership transfer")
	}
	if caller != pendingAdmin {
		panic("unauthorized: only the pending admin may accept")
	}
	admin = pendingAdmin
	pendingAdmin = ""
	chain.Emit("OwnershipTransferAccepted", "admin", admin.String())
}

// CancelOwnershipTransfer clears a staged handoff. Admin only.
func CancelOwnershipTransfer(cur realm) {
	assertAdmin(cur)
	if pendingAdmin == "" {
		panic("no pending ownership transfer")
	}
	cancelled := pendingAdmin
	pendingAdmin = ""
	chain.Emit("OwnershipTransferCancelled", "cancelled", cancelled.String())
}

// GetAdmin returns the address that holds admin.
func GetAdmin() string { return admin.String() }

// GetPendingAdmin returns the staged successor ("" when none).
func GetPendingAdmin() string { return pendingAdmin.String() }

// ── Fee recipient rotation ───────────────────────────────────

// ProposeFeeRecipient stages a new fallback fee recipient. Admin only.
func ProposeFeeRecipient(cur realm, recipient address) {
	assertAdmin(cur)
	if !recipient.IsValid() {
		panic("fee recipient must be a valid address")
	}
	pendingFeeRecipient = recipient
	chain.Emit("FeeRecipientProposed", "pending", recipient.String())
}

// AcceptFeeRecipient completes the rotation. Only the staged address may call
// it, which proves it can transact.
func AcceptFeeRecipient(cur realm) {
	caller := callerOf(cur)
	if pendingFeeRecipient == "" {
		panic("no pending fee recipient")
	}
	if caller != pendingFeeRecipient {
		panic("unauthorized: only the pending fee recipient may accept")
	}
	feeRecipient = pendingFeeRecipient
	pendingFeeRecipient = ""
	chain.Emit("FeeRecipientAccepted", "recipient", feeRecipient.String())
}

// CancelFeeRecipientProposal clears a staged fee recipient. Admin only.
func CancelFeeRecipientProposal(cur realm) {
	assertAdmin(cur)
	if pendingFeeRecipient == "" {
		panic("no pending fee recipient")
	}
	cancelled := pendingFeeRecipient
	pendingFeeRecipient = ""
	chain.Emit("FeeRecipientProposalCancelled", "cancelled", cancelled.String())
}

// GetFeeRecipient returns the fallback fee recipient.
func GetFeeRecipient() string { return feeRecipient.String() }

// GetPendingFeeRecipient returns the staged fee recipient ("" when none).
func GetPendingFeeRecipient() string { return pendingFeeRecipient.String() }

// basisPointsFee computes floor(amount*bps/10000) without overflowing the
// intermediate product. For nonnegative amount and bps <= 10000, the quotient
// product and final sum are <= amount; the remainder product is < 100000000.
// Callers retain their existing configured rates, recipients and rounding.
func basisPointsFee(amount, bps int64) int64 {
	if amount < 0 || bps < 0 || bps > 10000 {
		panic("invalid fee inputs")
	}
	return (amount/10000)*bps + ((amount%10000)*bps)/10000
}

// cleanText validates and sanitises user text before it is stored and
// rendered. It refuses input longer than max bytes, input that is not valid
// UTF-8 (the sanitiser would otherwise turn each bad byte into a 3-byte
// U+FFFD, storing up to three times the limit), and control or format
// characters (\p{Cc}, \p{Cf}: bidi overrides, zero-width characters), which
// could hide or reorder text. It then strips markdown-sensitive characters and
// line breaks and tabs, as v3 did. Stripping only removes bytes, so the result
// is within max; that is checked again because storage is bounded by it.
func cleanText(s, what string, max int) string {
	if len(s) > max {
		panic(ufmt.Sprintf("%s must be at most %d bytes", what, max))
	}
	if !utf8.ValidString(s) {
		panic(what + " must be valid UTF-8")
	}
	strip := false
	for _, c := range s {
		if isStripped(c) {
			strip = true
			continue
		}
		if c < 0x20 || c == 0x7f || (c >= 0x80 && c < 0xa0) || (mayBeFormat(c) && unicode.Is(unicode.Cf, c)) {
			panic(what + " contains invisible or control characters")
		}
	}
	if !strip {
		return s
	}
	var out strings.Builder
	for _, c := range s {
		if !isStripped(c) {
			out.WriteRune(c)
		}
	}
	clean := out.String()
	if len(clean) > max {
		panic(ufmt.Sprintf("%s must be at most %d bytes", what, max))
	}
	return clean
}

// isStripped reports the markdown-sensitive characters and line breaks and
// tabs removed from stored text, as in v3.
func isStripped(c rune) bool {
	switch c {
	case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
		return true
	}
	return false
}

// mayBeFormat is a cheap superset test for \p{Cf} (every format character is
// U+00AD, in U+0600..U+206F, or at or above U+FEFF), so common text skips the
// table lookup.
func mayBeFormat(c rune) bool {
	return c == 0xad || (c >= 0x600 && c <= 0x206f) || c >= 0xfeff
}

package escrow_v4

// The only chain/runtime/unsafe uses in this realm. Nothing here reads a
// caller from the stack and no crossing entrypoint is declared in this file:
// entrypoints authenticate with cur.IsCurrent() and cur.Previous(), and
// requireExactSend only checks the kind of the frame-verified caller it is
// handed.

import (
	"chain/runtime/unsafe"

	"gno.land/p/nt/ufmt/v0"
)

// publisherAtLoad captures the AddPackage signer during package
// initialization; it seeds admin and the fallback fee recipient.
func publisherAtLoad() address { return unsafe.OriginCaller() }

// requireExactSend panics unless caller (the entrypoint's cur.Previous()) is
// a direct user call and the transaction's send envelope holds exactly amount
// ugnot and no other denom. Only for a direct user call is the envelope
// credited to this realm, the message target; any other denom would be
// stranded here. The guard sits in this function, before the read, so the
// deployer's per-function fund-safety scan (lib/deploy.sh) sees it.
func requireExactSend(amount int64, caller realm) {
	if !caller.IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}
	sent := int64(0)
	for _, coin := range unsafe.OriginSend() {
		if coin.Denom != "ugnot" {
			panic("only ugnot is accepted, got " + coin.Denom)
		}
		sent += coin.Amount
	}
	if sent != amount {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", amount, sent))
	}
}

// realmAddress is this realm's own address, for the NF-2 solvency getter.
func realmAddress() address { return unsafe.CurrentRealm().Address() }

package escrow_v4

// Read-only views: NF-2 solvency getters, counters, governance reads, JSON
// views for frontends and Render. Nothing here changes state. (All of this
// sits in one file, like the state-changing code in escrow.gno, because every
// extra file costs AddPackage storage.)

import (
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"
	cfg "gno.land/r/samcrew/memba_market_config"
)

// ── NF-2 solvency getters (MAINNET_READINESS.md §3) ─────────────────────────
//
// Invariant the solvency monitor reconciles: realm balance >=
// TotalLiabilities(). totalLiable rises by the milestone amount in
// FundMilestone and falls by it at every point funds leave the realm.

// TotalLiabilities returns the ugnot the realm owes across funded, completed
// and disputed milestones.
func TotalLiabilities() int64 { return totalLiable }

// RealmAddress is the NF-2 canonical name for the realm's own address.
func RealmAddress() string { return realmAddress().String() }

// ── Slot and archive counters ─────────────────────────────────────────────

// GetActiveCount returns the number of open contracts (not completed or
// cancelled).
func GetActiveCount() int { return activeCount }

// GetClientActiveCount returns the open contracts created by client, bounded
// by MaxActivePerClient.
func GetClientActiveCount(client address) int { return clientActive(client) }

// GetLiveCount returns the contracts still stored: open ones plus settled ones
// their client has not archived.
func GetLiveCount() int { return contracts.Size() }

// GetArchivedCount returns the contracts deleted by ArchiveContract.
func GetArchivedCount() int { return archivedCount }

// GetCreatedCount returns every contract ever created; ids run from 0 to
// GetCreatedCount()-1 and are never reused.
func GetCreatedCount() int { return nextID }

// Value-only reads for the memba_dao escrow adapter, unchanged from escrow_v3:
// no Contract pointer or persistent milestone slice escapes. An archived
// contract reads as absent (Exists false).

type GovernanceMilestone struct {
	ID                                int
	Amount                            int64
	Status                            string
	FundedAt, CompletedAt, DisputedAt int64
	PreDisputeStatus                  string
}

type GovernanceContract struct {
	Exists                  bool
	ID, ContentHash, Status string
	Client, Freelancer      address
	Count                   int
	Milestones              [20]GovernanceMilestone
}

func GetGovernanceContract(id string) GovernanceContract {
	v, ok := contracts.Get(id)
	if !ok {
		return GovernanceContract{}
	}
	c := v.(*Contract)
	if len(c.Milestones) > MaxMilestones {
		panic("invalid escrow milestone count")
	}
	s := GovernanceContract{Exists: true, ID: c.ID, Status: string(c.Status), Client: c.Client, Freelancer: c.Freelancer, Count: len(c.Milestones), ContentHash: contentHash(c)}
	for i, m := range c.Milestones {
		s.Milestones[i] = GovernanceMilestone{ID: m.ID, Amount: m.Amount, Status: string(m.Status), FundedAt: m.FundedAt, CompletedAt: m.CompletedAt, DisputedAt: m.DisputedAt, PreDisputeStatus: string(m.PreDisputeStatus)}
	}
	return s
}

// contentHash digests the immutable metadata of a contract (parties, texts,
// creation height, milestone titles and amounts), not its state.
func contentHash(c *Contract) string {
	metadata := "escrow-metadata/v1" + escrowMetadataField(c.ID) + escrowMetadataField(string(c.Client)) + escrowMetadataField(string(c.Freelancer)) + escrowMetadataField(c.Title) + escrowMetadataField(c.Description) + escrowMetadataField(strconv.FormatInt(c.CreatedAt, 10)) + escrowMetadataField(strconv.Itoa(len(c.Milestones)))
	for _, m := range c.Milestones {
		metadata += escrowMetadataField(strconv.Itoa(m.ID)) + escrowMetadataField(m.Title) + escrowMetadataField(strconv.FormatInt(m.Amount, 10))
	}
	digest := sha256.Sum256([]byte(metadata))
	return hex.EncodeToString(digest[:])
}

type GovernanceFeeTerms struct {
	RawBPS, EffectiveBPS                             int64
	RawTreasury, FallbackTreasury, EffectiveTreasury address
}

func GetGovernanceFeeTerms() GovernanceFeeTerms {
	bps, treasury := resolveFee()
	return GovernanceFeeTerms{RawBPS: int64(cfg.GetFeeBPS(laneService)), EffectiveBPS: bps, RawTreasury: cfg.GetTreasury(), FallbackTreasury: feeRecipient, EffectiveTreasury: treasury}
}

func escrowMetadataField(value string) string { return strconv.Itoa(len(value)) + ":" + value }

// Structured read-only views for frontends (additive to the frozen API; they
// change no state and no existing behaviour). Every integer is a decimal
// string, absent values are null, and an unknown or archived id reads as
// {"exists":false,...}. Heights such as refundAt are pause-adjusted deadlines,
// assuming no further pause. Contract listings walk at most limit+1 entries
// of a per-party index, newest first.

const maxPageSize = 50

// indexPrefix keys the client index inside clientSlots (the per-client slot
// counters are keyed by the bare address, which never starts with "c/"): one
// tree instead of two keeps the package smaller.
const indexPrefix = "c/"

// GetContractJSON returns one contract as JSON.
func GetContractJSON(id string) string {
	v, ok := contracts.Get(id)
	if !ok {
		return `{"exists":false,"id":` + jstr(id) + `}`
	}
	c := v.(*Contract)
	var total, escrowed, released, refunded, fundedAt, refundAt, resolveAt int64
	pending := true
	var ms strings.Builder
	for i, m := range c.Milestones {
		total += m.Amount
		mRefund, mResolve := int64(0), int64(0)
		switch m.Status {
		case MsFunded:
			mRefund = deadline(m.FundedAt, m.fundedPauseMark, AutoRefundBlks)
			refundAt = minHeight(refundAt, mRefund)
			escrowed += m.Amount
		case MsDisputed:
			mResolve = deadline(m.DisputedAt, m.disputedPauseMark, AutoResolveBlks)
			resolveAt = minHeight(resolveAt, mResolve)
			escrowed += m.Amount
		case MsCompleted:
			escrowed += m.Amount
		case MsReleased:
			released += m.Amount
		case MsRefunded:
			refunded += m.Amount
		}
		if m.Status != MsPending {
			pending = false
		}
		fundedAt = minHeight(fundedAt, m.FundedAt)
		if i > 0 {
			ms.WriteString(",")
		}
		ms.WriteString(`{"index":` + jint(int64(i)) + `,"title":` + jstr(m.Title) +
			`,"amountUgnot":` + jint(m.Amount) + `,"status":` + jstr(string(m.Status)) +
			`,"fundedAtHeight":` + jheight(m.FundedAt) + `,"completedAtHeight":` + jheight(m.CompletedAt) +
			`,"disputedAtHeight":` + jheight(m.DisputedAt) + `,"refundAt":` + jheight(mRefund) +
			`,"resolveAt":` + jheight(mResolve) + `}`)
	}
	expireAt := int64(0)
	if pending && c.Status == StatusActive {
		expireAt = deadline(c.CreatedAt, c.createdPauseMark, UnfundedExpiryBlks)
	}
	return `{"exists":true,"id":` + jstr(c.ID) + `,"client":` + jstr(c.Client.String()) +
		`,"freelancer":` + jstr(c.Freelancer.String()) + `,"title":` + jstr(c.Title) +
		`,"description":` + jstr(c.Description) + `,"status":` + jstr(string(c.Status)) +
		`,"createdAtHeight":` + jint(c.CreatedAt) + `,"fundedAtHeight":` + jheight(fundedAt) +
		`,"refundAt":` + jheight(refundAt) + `,"expireAt":` + jheight(expireAt) + `,"resolveAt":` + jheight(resolveAt) +
		`,"milestones":[` + ms.String() + `],"totals":{"amountUgnot":` + jint(total) +
		`,"escrowedUgnot":` + jint(escrowed) + `,"releasedUgnot":` + jint(released) +
		`,"refundedUgnot":` + jint(refunded) + `}}`
}

// GetClientContractsJSON pages the live contracts a client created, newest
// first: {"items":[{"id","status","createdAtHeight"}...],"next":cursor|null}.
// before is "" for the first page or the previous page's next cursor; limit
// is clamped to 1..50.
func GetClientContractsJSON(client address, before string, limit int) string {
	return contractsPage(client, before, limit)
}

// GetPauseStateJSON returns PauseState() as JSON.
func GetPauseStateJSON() string {
	p := PauseState()
	return `{"paused":` + strconv.FormatBool(p.Paused) + `,"pausedAt":` + jheight(p.PausedAt) +
		`,"exitsReopenAt":` + jheight(p.ExitsReopenAt) + `,"exitsOpen":` + strconv.FormatBool(p.ExitsOpen) +
		`,"cooldownUntil":` + jint(p.CooldownUntil) + `,"pausedBlocks":` + jint(p.PausedBlocks) + `}`
}

func contractsPage(who address, before string, limit int) string {
	if limit < 1 {
		limit = 1
	} else if limit > maxPageSize {
		limit = maxPageSize
	}
	prefix := indexPrefix + who.String() + "/"
	end := prefix + "~" // after every digit
	if before != "" {
		n, err := strconv.Atoi(before)
		if err != nil || n < 0 || strconv.Itoa(n) != before {
			panic("invalid cursor: " + before)
		}
		end = indexKey(who, n)
	}
	var sb strings.Builder
	count, next, last := 0, "null", ""
	clientSlots.ReverseIterate(prefix, end, func(key string, _ any) bool {
		n, _ := strconv.Atoi(key[len(prefix):])
		id := strconv.Itoa(n)
		if id == before {
			return false // end is inclusive; the cursor itself was on the previous page
		}
		if count == limit {
			next = jstr(last)
			return true
		}
		c := getContract(id)
		if count > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`{"id":` + jstr(id) + `,"status":` + jstr(string(c.Status)) +
			`,"createdAtHeight":` + jint(c.CreatedAt) + `}`)
		count++
		last = id
		return false
	})
	return `{"items":[` + sb.String() + `],"next":` + next + `}`
}

// indexKey orders a party's contracts by id: 10-digit zero padding.
func indexKey(who address, id int) string {
	s := strconv.Itoa(id)
	return indexPrefix + who.String() + "/" + strings.Repeat("0", 10-len(s)) + s
}

// deadline is the height at which a clock started at since (pause mark taken
// then) reaches span unpaused blocks, assuming no pause after the current one.
func deadline(since, mark, span int64) int64 {
	now := runtime.ChainHeight()
	if inBlockingWindow(now) {
		now = pausedAt + MaxPauseBlks
	}
	return since + span + pausedBlocksAt(now) - mark
}

func minHeight(a, b int64) int64 {
	if a == 0 || (b != 0 && b < a) {
		return b
	}
	return a
}

func jint(n int64) string { return `"` + strconv.FormatInt(n, 10) + `"` }

// jheight encodes 0 (not set) as null.
func jheight(n int64) string {
	if n == 0 {
		return "null"
	}
	return jint(n)
}

// jstr quotes s as a JSON string. Stored text is valid UTF-8 without control
// characters; ids passed by callers are escaped the same way.
func jstr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b.WriteByte('\\')
			b.WriteRune(r)
		case r < 0x20:
			b.WriteString(`\u00`)
			b.WriteByte("0123456789abcdef"[r>>4])
			b.WriteByte("0123456789abcdef"[r&15])
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// Render() contract:
//   Home — Render("") or Render("page/N"):
//     # Escrow Contracts
//     | ID | Title | Client | Freelancer | Status | Total |
//     (RenderPageSize live contracts per page, in tree order)
//   Detail — Render("contract/ID"):
//     # Title
//     **Client:** g1...
//     **Freelancer:** g1...
//     **Status:** active
//     ## Milestones
//     - **Milestone Title** — 1000000 ugnot [funded]
//   Stats — Render("stats"): counters only, no iteration.
// Archived contracts are gone from every view.

// RenderPageSize is the number of contracts listed per home page.
const RenderPageSize = 20

func Render(path string) string {
	switch {
	case path == "":
		return renderHome(1)
	case strings.HasPrefix(path, "page/"):
		page, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || page < 1 {
			return "# 404\nNot found: " + path
		}
		return renderHome(page)
	case strings.HasPrefix(path, "contract/"):
		return renderContract(strings.TrimPrefix(path, "contract/"))
	case path == "stats":
		return renderStats()
	}
	return "# 404\nNot found: " + path
}

func renderHome(page int) string {
	var sb strings.Builder
	sb.WriteString("# Escrow Contracts\n\n")
	sb.WriteString("Milestone-based escrow for freelance services on Gno.\n\n")

	live := contracts.Size()
	if live == 0 {
		sb.WriteString("*No contracts yet.*\n")
		return sb.String()
	}
	offset := (page - 1) * RenderPageSize
	if offset >= live {
		return "# 404\nNo page " + strconv.Itoa(page)
	}

	sb.WriteString("| ID | Title | Client | Freelancer | Status | Total |\n")
	sb.WriteString("| --- | --- | --- | --- | --- | --- |\n")
	contracts.IterateByOffset(offset, RenderPageSize, func(_ string, value any) bool {
		c := value.(*Contract)
		sb.WriteString(ufmt.Sprintf("| %s | [%s](:contract/%s) | %s | %s | %s | %d ugnot |\n",
			c.ID, c.Title, c.ID, truncAddr(c.Client), truncAddr(c.Freelancer),
			string(c.Status), contractTotal(c)))
		return false
	})
	if offset+RenderPageSize < live {
		sb.WriteString(ufmt.Sprintf("\n[Next page](:page/%d)\n", page+1))
	}
	return sb.String()
}

func renderContract(id string) string {
	val, exists := contracts.Get(id)
	if !exists {
		return "# 404\nContract not found: " + id
	}
	c := val.(*Contract)

	var sb strings.Builder
	sb.WriteString("# " + c.Title + "\n\n")
	if len(c.Description) > 0 {
		sb.WriteString(c.Description + "\n\n")
	}
	sb.WriteString("**ID:** " + c.ID + "\n")
	sb.WriteString("**Client:** " + c.Client.String() + "\n")
	sb.WriteString("**Freelancer:** " + c.Freelancer.String() + "\n")
	sb.WriteString("**Status:** " + string(c.Status) + "\n")
	sb.WriteString("**Created:** block " + strconv.FormatInt(c.CreatedAt, 10) + "\n\n")
	sb.WriteString("**Total Value:** " + strconv.FormatInt(contractTotal(c), 10) + " ugnot\n\n")

	sb.WriteString("## Milestones\n\n")
	for _, ms := range c.Milestones {
		sb.WriteString(ufmt.Sprintf("- **%s** — %d ugnot [%s]", ms.Title, ms.Amount, string(ms.Status)))
		if ms.FundedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (funded block %d)", ms.FundedAt))
		}
		if ms.CompletedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (completed block %d)", ms.CompletedAt))
		}
		if ms.DisputedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (disputed block %d)", ms.DisputedAt))
		}
		sb.WriteString("\n")
	}
	return sb.String()
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Stats\n\n")
	sb.WriteString(ufmt.Sprintf("**Created:** %d\n", nextID))
	sb.WriteString(ufmt.Sprintf("**Open:** %d (at most %d per client)\n", activeCount, MaxActivePerClient))
	sb.WriteString(ufmt.Sprintf("**Settled, not archived:** %d\n", contracts.Size()-activeCount))
	sb.WriteString(ufmt.Sprintf("**Archived:** %d\n", archivedCount))
	sb.WriteString(ufmt.Sprintf("**Liabilities:** %d ugnot\n", totalLiable))
	p := PauseState()
	switch {
	case !p.Paused:
		sb.WriteString("**Paused:** no\n")
	case !p.ExitsOpen:
		sb.WriteString(ufmt.Sprintf("**Paused:** yes, since block %d; exits reopen at block %d\n", p.PausedAt, p.ExitsReopenAt))
	default:
		sb.WriteString(ufmt.Sprintf("**Paused:** new contracts and funding only, since block %d\n", p.PausedAt))
	}
	return sb.String()
}

// contractTotal cannot overflow: CreateContract refuses totals above int64.
func contractTotal(c *Contract) int64 {
	total := int64(0)
	for _, ms := range c.Milestones {
		total += ms.Amount
	}
	return total
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// Package `nft` draws the Settlers, pixel-art gnomes.
// The art is dedicated to the public domain under CC0 1.0, see Credits.
package nft

const (
	// Style is the ID of the art style.
	Style = "settlers-v1"

	// Credits is the license of the art.
	Credits = "The art of the Settlers is dedicated to the public domain under " +
		"[CC0 1.0 Universal](https://creativecommons.org/publicdomain/zero/1.0/)"
)

package nft

const (
	gridW = 24
	gridH = 32
	half  = 12 // columns of the left half, where rows are written
)

// span is a horizontal range of pixels, x0 to x1 inclusive.
type span struct{ y, x0, x1 int }

// BuildGrid returns the pixel grid of a gnome, as 32 rows of 24 palette keys ('.' is transparent).
// Traits must be valid.
func BuildGrid(t Traits) []string {
	g := buildGrid(t)

	rows := make([]string, gridH)
	for y := 0; y < gridH; y++ {
		row := make([]byte, gridW)
		for x := 0; x < gridW; x++ {
			c := g[y*gridW+x]
			if c == 0 {
				c = '.'
			}
			row[x] = c
		}
		rows[y] = string(row)
	}
	return rows
}

// buildGrid draws all the layers of a gnome. The grid has a byte per pixel, row by row, and 0 is transparent.
func buildGrid(t Traits) []byte {
	if err := t.Validate(); err != nil {
		panic("settlers: " + err.Error())
	}

	g := make([]byte, gridW*gridH)

	draw(g, body, 19)
	if t.Beard == 0 {
		draw(g, head+headNoBeard, 13)
	} else {
		switch t.Beard {
		case 1:
			draw(g, beardLong, 19)
		case 2:
			draw(g, beardPointy, 19)
		default:
			draw(g, beardRound, 19)
		}
		draw(g, head+headBeard, 13)
	}

	if t.Glasses > 0 {
		for _, p := range glassesFrame {
			put(g, p[0], p[1], 'g')
		}
		for _, p := range glassesEyes {
			put(g, p[0], p[1], 'e')
		}
	}

	if t.HatShape == 0 {
		draw(g, hatTall, 0)
	} else {
		drawBentHat(g, t.Flip == 1)
	}
	draw(g, brim, 11)
	draw(g, boots, 28)
	return g
}

// draw draws rows, that are the left half of the sprite, starting at row y0. The right half is
// the left half mirrored, where light tones are swapped by their shaded twin.
func draw(g []byte, rows string, y0 int) {
	for i := 0; i*half < len(rows); i++ {
		y := y0 + i
		if y < 0 || y >= gridH {
			continue
		}

		row := rows[i*half : (i+1)*half]
		for j := 0; j < half; j++ {
			c := row[j]
			if c != '.' {
				g[y*gridW+j] = c
				g[y*gridW+gridW-1-j] = swapTable[c]
			}
		}
	}
}

func put(g []byte, x, y int, c byte) {
	if x >= 0 && x < gridW && y >= 0 && y < gridH {
		g[y*gridW+x] = c
	}
}

// drawBentHat draws the hat with the tip that falls to the right, or to the left when flipped.
//
// It is written without function calls (no closures or helpers), because they are the most
// expensive thing in Gno. The fill has a border of one cell, so neighbors never need a bounds check.
func drawBentHat(g []byte, flip bool) {
	const (
		rows   = coneY0 + len(coneK) + 1 // rows of the hat, one more than the cone for its outline
		stride = gridW + 2
	)
	var fill [(rows + 2) * stride]bool // No maps are used to keep it deterministic

	for i, k := range coneK {
		for x := half - k; x < half+k; x++ {
			if flip {
				fill[(coneY0+i+1)*stride+gridW-x] = true // mirrored column gridW-1-x, plus the border
			} else {
				fill[(coneY0+i+1)*stride+x+1] = true
			}
		}
	}
	for _, s := range tailSpans {
		for x := s.x0; x <= s.x1; x++ {
			if flip {
				fill[(s.y+1)*stride+gridW-x] = true
			} else {
				fill[(s.y+1)*stride+x+1] = true
			}
		}
	}

	for y := 0; y < rows; y++ {
		for x := 0; x < gridW; x++ {
			i := (y+1)*stride + x + 1
			if !fill[i] {
				continue
			}
			left, right, up, down := fill[i-1], fill[i+1], fill[i-stride], fill[i+stride]

			// Shading
			c := byte('H')
			if !left {
				if y%2 == 1 {
					c = 'h'
				}
			} else if !right || !down {
				c = 'j'
			}
			g[y*gridW+x] = c

			// Outline. It only touches pixels that are not part of the hat, so it doesn't matter
			// that it is done in the same pass as the shading.
			if !left && x > 0 {
				g[y*gridW+x-1] = 'o'
			}
			if !right && x < gridW-1 {
				g[y*gridW+x+1] = 'o'
			}
			if !up && y > 0 {
				g[(y-1)*gridW+x] = 'o'
			}
			if !down {
				g[(y+1)*gridW+x] = 'o'
			}
		}
	}
}

package nft

import (
	"encoding/base64"
	"strconv"
)

// CanonicalSize is the width and height in pixels of the image used for NFTs.
const CanonicalSize = 512

// Options are the options to render a gnome.
type Options struct {
	// Size is the width and the height of the image in pixels, because the image is a square.
	// Multiples of 32 keep every art pixel as a whole number of screen pixels.
	// Zero omits the width and height, so that the image scales to its container.
	Size int

	// NoBackground omits the background.
	NoBackground bool

	// BackgroundColor replaces the color of the background, in "#rrggbb" format.
	BackgroundColor string
}

// RenderSVG renders the gnome as an SVG document.
// Traits must be valid.
// The same traits and options always give the same bytes.
func RenderSVG(t Traits, o Options) string {
	return render(t, o, &rawSyntax)
}

// RenderSeed renders the gnome of a seed as an SVG document.
func RenderSeed(seed string, o Options) string {
	return RenderSVG(NewTraits(seed), o)
}

// RenderDataURI renders the gnome as a "data:image/svg+xml;charset=utf-8," URI, percent-encoded.
//
// Cheapest way to embed a gnome.
// SVG is written encoded, instead of encoding it afterwards.
// Traits must be valid.
func RenderDataURI(t Traits, o Options) string {
	return "data:image/svg+xml;charset=utf-8," + render(t, o, &uriSyntax)
}

// DataURI encodes an SVG document as a "data:image/svg+xml;base64," URI.
// It is slower than RenderDataURI, use it when Base64 is needed.
func DataURI(svg string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

// syntax define the fixed pieces of the SVG document, that are the same for every gnome.
type syntax struct {
	open       string // start of the svg element, up to its size
	widthOpen  string
	heightOpen string
	sizeClose  string
	openEnd    string // end of the start of the svg element
	rectOpen   string // background, before its color
	rectClose  string
	pathOpen   string // before the color
	pathMid    string // after the color, before the segments
	pathClose  string
	end        string
	mHead      []string // start of a segment, by x
}

// rawSyntax contains the fixed pieces of the SVG document.
var rawSyntax = syntax{
	open:       `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-4 0 32 32"`,
	widthOpen:  ` width="`,
	heightOpen: `" height="`,
	sizeClose:  `"`,
	openEnd:    ` shape-rendering="crispEdges">`,
	rectOpen:   `<rect x="-4" width="32" height="32" fill="#`,
	rectClose:  `"/>`,
	pathOpen:   `<path fill="#`,
	pathMid:    `" d="`,
	pathClose:  `"/>`,
	end:        `</svg>`,
	mHead:      rawMHead[:],
}

// uriSyntax contains the fixes pieces of the SVG document encoded for data URI.
var uriSyntax = syntax{
	open:       `%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%22-4%200%2032%2032%22`,
	widthOpen:  `%20width=%22`,
	heightOpen: `%22%20height=%22`,
	sizeClose:  `%22`,
	openEnd:    `%20shape-rendering=%22crispEdges%22%3E`,
	rectOpen:   `%3Crect%20x=%22-4%22%20width=%2232%22%20height=%2232%22%20fill=%22%23`,
	rectClose:  `%22/%3E`,
	pathOpen:   `%3Cpath%20fill=%22%23`,
	pathMid:    `%22%20d=%22`,
	pathClose:  `%22/%3E`,
	end:        `%3C/svg%3E`,
	mHead:      uriMHead[:],
}

// maxGroups is the biggest number of different colors of a gnome: 22 keys.
const maxGroups = 24

// render draws the gnome:
//   - Pixels are scanned row by row, and horizontal runs of the same key are one segment.
//   - Segments are grouped by color, in the order in which each color appears first.
func render(t Traits, o Options, s *syntax) string {
	g := buildGrid(t)
	bg := bgColors[t.Background]
	if o.BackgroundColor != "" {
		bg = hexColor(o.BackgroundColor)
	}

	var (
		groupOf    [128]uint8 // group of a key plus one, or 0 when the key was not seen
		groupColor [maxGroups]string
		groupPath  [maxGroups]string
		groups     int
	)
	for y := 0; y < gridH; y++ {
		row := g[y*gridW : (y+1)*gridW]
		for x := 0; x < gridW; {
			c := row[x]
			if c == 0 {
				x++
				continue
			}

			n := 1
			for x+n < gridW && row[x+n] == c {
				n++
			}

			gi := int(groupOf[c])
			if gi == 0 {
				// First time that the key is seen, its color might be already used by another key
				color := colorOf(t, c)
				for i := 0; i < groups; i++ {
					if groupColor[i] == color {
						gi = i + 1
						break
					}
				}

				if gi == 0 {
					groupColor[groups] = color
					groups++
					gi = groups
				}

				groupOf[c] = uint8(gi)
			}

			gi--
			groupPath[gi] += s.mHead[x] + nums[y] + runTail[n]
			x += n
		}
	}

	out := s.open
	if o.Size > 0 {
		px := strconv.Itoa(o.Size)
		out += s.widthOpen + px + s.heightOpen + px + s.sizeClose
	}

	out += s.openEnd
	if !o.NoBackground {
		out += s.rectOpen + bg + s.rectClose
	}

	for i := 0; i < groups; i++ {
		out += s.pathOpen + groupColor[i] + s.pathMid + groupPath[i] + s.pathClose
	}
	return out + s.end
}

// colorOf returns the color of a palette key, in hex digits.
func colorOf(t Traits, key byte) string {
	if c := fixedColor(key); c != "" {
		return c
	}

	skin := int(t.Skin) * 3
	hat := int(t.Hat) * 3
	beard := int(t.BeardColor) * 3
	tunic := int(t.Tunic) * 3

	switch key {
	case 't':
		return skinColors[skin]
	case 's':
		return skinColors[skin+1]
	case 'u':
		return skinColors[skin+2]
	case 'h':
		return hatColors[hat]
	case 'H':
		return hatColors[hat+1]
	case 'j':
		return hatColors[hat+2]
	case 'w':
		return beardColors[beard]
	case 'W':
		return beardColors[beard+1]
	case 'x':
		return beardColors[beard+2]
	case 'c':
		return tunicColors[tunic]
	case 'C':
		return tunicColors[tunic+1]
	case 'd':
		return tunicColors[tunic+2]
	case 'g':
		return glassesColors[t.Glasses-1]
	}
	panic("unknown palette key " + string(rune(key)))
}

// hexColor checks a "#rrggbb" color and returns its hex digits.
func hexColor(color string) string {
	if len(color) != 7 || color[0] != '#' {
		panic("invalid background color, expected #rrggbb")
	}

	for i := 1; i < 7; i++ {
		c := color[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			panic("invalid background color, expected #rrggbb")
		}
	}
	return color[1:]
}

package nft

import (
	"crypto/sha256"
	"errors"
)

var (
	beardColorNames = [...]string{"White", "Grey", "Ginger", "Brown"}
	beardShapeNames = [...]string{"None", "Long", "Pointy", "Round"}
	backgroundNames = [...]string{"Sky", "Sand", "Mint", "Lilac", "Blush"}
	glassesNames    = [...]string{"None", "Black", "Gold", "Red", "Teal"}
	hatNames        = [...]string{"Red", "Blue", "Green", "Purple", "Orange"}
	skinNames       = [...]string{"Light", "Medium", "Deep"}
	tunicNames      = [...]string{"Sky", "Leaf", "Clay", "Rose", "Sun"}
)

// Attribute is a named trait of a gnome.
type Attribute struct {
	Type  string
	Value string
}

// Traits describe a gnome.
type Traits struct {
	Skin       uint8
	Hat        uint8
	BeardColor uint8
	Tunic      uint8
	Background uint8
	HatShape   uint8 // 0 pointy, 1 bent
	Flip       uint8 // 0 or 1, no effect on pointy hats
	Glasses    uint8
	Beard      uint8
}

// NewTraits derives the traits of the gnome from a seed.
// A single seed always generate the same traits.
// Use `Validate()` to check traits before drawing.
func NewTraits(seed string) Traits {
	data := sha256.Sum256([]byte(seed))
	t := Traits{
		Skin:       data[0] % 3,
		Hat:        data[1] % 5,
		BeardColor: data[2] % 4,
		Tunic:      data[3] % 5,
		Background: data[4] % 5,
		Flip:       data[6] & 1,
	}

	// Gnome with bent hat, about 35%
	if data[5] < 90 {
		t.HatShape = 1
	}

	// Gnome with glasses, about 30%
	if data[7] < 77 {
		t.Glasses = data[8]%4 + 1
	}

	// Gnome without beard is a rare trait, about 4%
	if data[9] >= 10 {
		t.Beard = data[10]%3 + 1
	}
	return t
}

// Validate checks that all the traits are in range.
func (t Traits) Validate() error {
	switch {
	case t.Skin > 2:
		return errors.New("invalid skin")
	case t.Hat > 4:
		return errors.New("invalid hat color")
	case t.BeardColor > 3:
		return errors.New("invalid beard color")
	case t.Tunic > 4:
		return errors.New("invalid tunic")
	case t.Background > 4:
		return errors.New("invalid background")
	case t.HatShape > 1:
		return errors.New("invalid hat shape")
	case t.Flip > 1:
		return errors.New("invalid flip")
	case t.Glasses > 4:
		return errors.New("invalid glasses")
	case t.Beard > 3:
		return errors.New("invalid beard")
	}
	return nil
}

// Normalized returns the traits with the flip cleared when it has no effect.
// Two traits that draw the same gnome have the same normalized traits, so
// this is the value to compare and to keep when gnomes must be different.
func (t Traits) Normalized() Traits {
	// Clear trait when hat is pointy.
	if t.HatShape == 0 {
		t.Flip = 0
	}
	return t
}

// Attributes returns the traits of a gnome with their names.
// It panics when traits are not valid.
func (t Traits) Attributes() []Attribute {
	if err := t.Validate(); err != nil {
		panic(err.Error())
	}

	hat := "Pointed"
	if t.HatShape == 1 {
		hat = "Bent tip (right)"
		if t.Flip == 1 {
			hat = "Bent tip (left)"
		}
	}

	return []Attribute{
		{"Skin", skinNames[t.Skin]},
		{"Hat color", hatNames[t.Hat]},
		{"Hat", hat},
		{"Beard color", beardColorNames[t.BeardColor]},
		{"Beard", beardShapeNames[t.Beard]},
		{"Tunic", tunicNames[t.Tunic]},
		{"Glasses", glassesNames[t.Glasses]},
		{"Background", backgroundNames[t.Background]},
	}
}

// Pack packs the traits in 20 bits.
func Pack(t Traits) uint32 {
	// Bits:
	//   0-1   skin
	//   2-4   hat
	//   5-6   beard color
	//   7-9   tunic
	//   10-12 background
	//   13    hat shape
	//   14    flip
	//   15-17 glasses
	//   18-19 beard
	return uint32(t.Skin) |
		uint32(t.Hat)<<2 |
		uint32(t.BeardColor)<<5 |
		uint32(t.Tunic)<<7 |
		uint32(t.Background)<<10 |
		uint32(t.HatShape)<<13 |
		uint32(t.Flip)<<14 |
		uint32(t.Glasses)<<15 |
		uint32(t.Beard)<<18
}

// Unpack unpacks the traits.
// It does not check the values, use FromPacked for untrusted input.
func Unpack(v uint32) Traits {
	return Traits{
		Skin:       uint8(v & 3),
		Hat:        uint8((v >> 2) & 7),
		BeardColor: uint8((v >> 5) & 3),
		Tunic:      uint8((v >> 7) & 7),
		Background: uint8((v >> 10) & 7),
		HatShape:   uint8((v >> 13) & 1),
		Flip:       uint8((v >> 14) & 1),
		Glasses:    uint8((v >> 15) & 7),
		Beard:      uint8((v >> 18) & 3),
	}
}

// FromPacked unpacks traits and checks them.
func FromPacked(v uint32) (Traits, error) {
	if v>>20 != 0 {
		return Traits{}, errors.New("invalid packed traits")
	}

	t := Unpack(v)
	if err := t.Validate(); err != nil {
		return Traits{}, err
	}
	return t, nil
}
